import{z as n,x as B,o as E,c as p,q as t,j as o,D as e,d as s,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"热迁移","description":"","frontmatter":{"title":"热迁移","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/live-migration.md","filePath":"cs/live-migration.md","lastUpdated":1791063341000}'),A={name:"cs/live-migration.md"};function c(d,a,m,h,C,_){const r=B("Mermaid");return E(),p("div",null,[a[2]||(a[2]=t('<h1 id="热迁移" tabindex="-1">热迁移 <a class="header-anchor" href="#热迁移" aria-label="Permalink to &quot;热迁移&quot;">​</a></h1><div class="epigraph"><p>热迁移迭代拷贝客户内存，再短暂停机拷剩余脏页与设备状态；postcopy 用 [userfaultfd](/cs/userfaultfd) 在目标上按缺页拉。 </p><footer>—— 据 Clark et al., Live Migration of Virtual Machines, NSDI 2005；KVM 迁移文档</footer></div><p><a href="/cs/memory-balloon">气球</a> 改变内存集合。<a href="/cs/clock-virtualization">时钟</a> 必须在切瞬间对齐。缺口是 <strong>live migration</strong> 算法：预拷 vs 后拷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>precopoy：循环拷脏，直到脏率可接受，downtime 拷 vCPU。postcopy：先切，缺页从源拉。缺口：设备状态、<a href="/cs/sriov-passthrough">SR-IOV</a> 几乎不能迁；与 <a href="/cs/nfs-semantics">NFS</a> 上的磁盘。本课不把 RDMA 迁移实现写完。</p><p><span class="marginnote">术语翻译：脏页就是「拷过去之后又被客户机改写过的页」——目标上那份立刻过期，只能下一轮重拷。预拷的全部技巧，就是让这个集合一轮比一轮小，直到一轮就能拷完。</span></p><p><span class="marginnote">脏日志靠 EPT 写保护或 log dirty。对象是 VM 状态机，不是容器 runc 迁——容器后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建目标 VM → 迭代内存 → 停 → 切网络 → 跑。对照 <a href="/cs/fs-snapshots">fs 快照</a>：一个钉存储根，一个搬运行态。对照 sendfile：块在宿主之间，不是文件语义保证。对照 kexec：同机换核，不是跨机。</p>',9)),(E(),o(l,null,{default:e(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E9%A2%84%E6%8B%B7%E8%84%8F%E9%A1%B5%22%5D%20--%3E%20DIRTY%5B%22%E6%94%B6%E6%95%9B%22%5D%0A%20%20DIRTY%20--%3E%20STOP%5B%22%E7%9F%AD%E6%9A%82%E5%81%9C%E6%9C%BA%22%5D%0A%20%20STOP%20--%3E%20RUN%5B%22%E7%9B%AE%E6%A0%87%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20POST%5B%22postcopy%22%5D%20--%3E%20UFFD%5B%22%E7%BC%BA%E9%A1%B5%E4%BB%8E%E6%BA%90%E6%8B%89%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>热迁移把「机器」收成可复制的内存+设备检查点，使维护不停服务。收敛失败（脏太快）是经典坑。不要写成云产品 SLA。与 <a href="/cs/dm-crypt">dm-crypt</a>：盘可共享存储，只迁 RAM。</p><p><span class="marginnote">数字实例：内存 8 GB、链路 1 GB/s。客户机每秒只写 0.5 GB 时，两三轮就收敛；若每秒写超过 1 GB，每轮新产生的脏页比拷走的还多，停机时刻永远等不来——这就是收敛失败的判据。</span></p><p>安全：迁移通道要加密，否则内存明文在网上。</p><p>实现上：脏页率高于带宽则 precopy 永不收敛，要限 vCPU 或改 postcopy。磁盘必须是共享存储或一并拷。VF 直通要先解绑。 读法上只引用<a href="/cs/memory-balloon">上一课</a>的结论，不把对象换成训练推理或限价簿。</p>',5)),(E(),o(l,null,{default:e(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E7%AC%AC%201%20%E8%BD%AE%EF%BC%9A%E6%8B%B7%E5%85%A8%E9%83%A8%E5%86%85%E5%AD%98%22%5D%20--%3E%20W%5B%22%E5%AE%A2%E6%88%B7%E6%9C%BA%E7%BB%A7%E7%BB%AD%E8%B7%91%EF%BC%8C%E4%BA%A7%E7%94%9F%E6%96%B0%E8%84%8F%E9%A1%B5%22%5D%0A%20%20W%20--%3E%20R2%5B%22%E7%AC%AC%202%20%E8%BD%AE%EF%BC%9A%E5%8F%AA%E6%8B%B7%E8%84%8F%E6%97%A5%E5%BF%97%E9%87%8C%E7%9A%84%E9%A1%B5%22%5D%0A%20%20R2%20--%3E%20CHK%7B%22%E6%9C%AC%E8%BD%AE%E8%84%8F%E9%A1%B5%E9%87%8F%20%E2%89%A4%20%E4%B8%80%E8%BD%AE%E8%83%BD%E6%8B%B7%E7%9A%84%E9%87%8F%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20STOP%5B%22%E6%94%B6%E6%95%9B%EF%BC%9A%E5%81%9C%E6%9C%BA%E6%8B%B7%E6%9C%80%E5%90%8E%E4%B8%80%E6%89%B9%E5%B9%B6%E5%88%87%E6%8D%A2%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20SLOW%5B%22%E9%99%8D%E8%84%8F%E7%8E%87%EF%BC%9A%E9%99%90%20vCPU%20%E6%88%96%E6%94%B9%20postcopy%22%5D%0A%20%20SLOW%20--%3E%20W%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：以为迁移只是「把内存拷过去」。VF 直通设备的寄存器与队列状态几乎搬不走，要先解绑回落到软件接口；存储要么共享（只迁 RAM），要么连盘一起拷，否则目标机一跑就找错盘。</span></p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>热迁移</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 downtime 调参。不保证 GPU 直通可迁。下一课套娃：嵌套虚拟化。</p><p>版本字段会变，课序钉的是机制对象「热迁移」，不是某一主线内核的结构体名。 后课默认：VM 可迭代拷内存后切换。L1 上再跑 L2，下一课嵌套。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预拷收敛脏页；postcopy 用缺页拉。</li><li>直通设备是迁移敌人。</li><li>嵌套虚拟化是下一课。</li><li>出处：Clark et al., NSDI 2005；KVM migration。</li></ul>',8))])}const u=n(A,[["render",c]]);export{D as __pageData,u as default};
